import 'dart:convert';
import 'dart:typed_data';
import 'dart:ui';

import 'package:flutter_test/flutter_test.dart';
import 'package:panelist/core/imaging/image_header.dart';

/// 7x3 images generated with ImageMagick.
const _fixtures = {
  'a.jpg': '',
  'p.jpg': '',
  'a.png': '',
  'a.gif': 'R0lGODlhBwADAPAAAP8AAAAAACH5BAAAAAAALAAAAAAHAAMAAAIEhI+pBQA7',
  'a.bmp': 'Qk3SAAAAAAAAAIoAAAB8AAAABwAAAAMAAAABABgAAAAAAEgAAAAAAAAAAAAAAAAAAAAAAAAAAAD/AAD/AAD/AAAAAAAA/0JHUnOPwvUoUbgeFR6F6wEzMzMTZmZmJmZmZgaZmZkJPQrXAyhcjzIAAAAAAAAAAAAAAAAEAAAAAAAAAAAAAAAAAAAAAAD/AAD/AAD/AAD/AAD/AAD/AAD/AAAAAAD/AAD/AAD/AAD/AAD/AAD/AAD/AAAAAAD/AAD/AAD/AAD/AAD/AAD/AAD/AAAA',
  'a.webp': 'UklGRjwAAABXRUJQVlA4IDAAAADQAQCdASoHAAMAAgA0JaACdLoB+AADsAD+8MQL/yC5YXXI1/8gP+QH/ID/+PIAAAA=',
  'l.webp': 'UklGRhwAAABXRUJQVlA4TA8AAAAvBoAAAAcQ/Y/+ByKi/wEA',
  'x.webp': 'UklGRmAAAABXRUJQVlA4WAoAAAAQAAAABgAAAgAAQUxQSAoAAAABB1DAiAhERP8DVlA4IDAAAADQAQCdASoHAAMAAgA0JaACdLoB+AADsAD+8MQL/yC5YXXI1/8gP+QH/ID/+PIAAAA=',
};

void main() {
  for (final MapEntry(:key, :value) in _fixtures.entries) {
    test('reads $key', () {
      expect(readImageSize(base64Decode(value)), const Size(7, 3));
    });
  }

  test('truncated JPEG returns null (caller can retry with more bytes)', () {
    final jpg = base64Decode(_fixtures['a.jpg']!);
    expect(readImageSize(Uint8List.sublistView(jpg, 0, 30)), isNull);
  });

  test('unknown data returns null', () {
    expect(readImageSize(Uint8List.fromList(List.filled(64, 7))), isNull);
    expect(readImageSize(Uint8List(3)), isNull);
  });
}
